@Override public void stepChanged(final String stepName,final String delegateName,final GamePlayer player,final int round,final String displayName,final boolean loadedFromSavedGame){
  if (loadedFromSavedGame) {
    return;
  }
  SwingUtilities.invokeLater(() -> {
    try {
      if (currentRound != round) {
        currentRound=round;
        gameData.getHistory().getHistoryWriter().startNextRound(currentRound);
      }
      gameData.getHistory().getHistoryWriter().startNextStep(stepName,delegateName,player,displayName);
    } catch (RuntimeException e) {
      e.printStackTrace();
    }
  });
}
